     3|/**
     4| * Structured engineering contract used by the IVX senior-developer runtime.
     5| * It turns an unstructured owner request into a bounded, auditable execution
     6| * brief before code mutation, testing, or deployment can begin.
     7| */
     8|export const IVX_SENIOR_DEVELOPER_CAPABILITY_MARKER = 'ivx-senior-developer-capability-engine-v1-2026-08-01';
     9|
    10|export type IVXSeniorDeveloperCapability =
    11|  | 'vague_goal_code_generation'
    12|  | 'log_driven_debugging'
    13|  | 'feature_architecture'
    14|  | 'novel_problem_adaptation'
    15|  | 'continuous_delivery';
    16|
    17|export type IVXEngineeringEvidenceKind =
    18|  | 'repository_inspection'
    19|  | 'log_signal'
    20|  | 'hypothesis'
    21|  | 'implementation'
    22|  | 'test_result'
    23|  | 'typecheck_result'
    24|  | 'commit'
    25|  | 'deployment'
    26|  | 'production_verification';
