    52|  };
    53|  adaptation: {
    54|    isNovel: boolean;
    55|    approach: string;
    56|    fallback: string;
    57|  };
    58|  evidenceRequirements: IVXEngineeringEvidenceRequirement[];
    59|  requiresOwnerApprovalForMutation: true;
    60|  requiresOwnerApprovalForDeployment: true;
    61|};
    62|
    63|function normalized(goal: string): string {
    64|  return goal.trim().toLowerCase().replace(/\s+/g, ' ');
    65|}
    66|
    67|function stableTaskId(goal: string): string {
    68|  return createHash('sha256').update(goal.trim()).digest('hex').slice(0, 16);
    69|}
    70|
    71|function unique<T>(values: T[]): T[] {
    72|  return [...new Set(values)];
    73|}
    74|
    75|/** Identifies the concrete engineering modes an owner request requires. */
    76|export function classifySeniorDeveloperCapabilities(goal: string): IVXSeniorDeveloperCapability[] {
    77|  const text = normalized(goal);
    78|  const capabilities: IVXSeniorDeveloperCapability[] = [];
    79|  const debug = /\b(debug|diagnos|root cause|logs?|trace|stack trace|crash|error|failure|broken|failing|timeout|exception)\b/.test(text);
    80|  const architecture = /\b(architect|architecture|end[- ]to[- ]end|new feature|new system|platform|workflow|design)\b/.test(text);
    81|  const delivery = /\b(build|test|verify|commit|deploy|ship|production|release|continuous)\b/.test(text);
    82|  const novel = /\b(novel|unfamiliar|unknown|never (?:seen|built)|new kind|not designed)\b/.test(text);
    83|  const vagueBuild = /\b(build|create|make|implement|add|generate|write)\b/.test(text)
    84|    && !/\bfrom ['"`].+['"`] to ['"`].+['"`]\b/.test(text);
    85|
    86|  if (vagueBuild) capabilities.push('vague_goal_code_generation');
    87|  if (debug) capabilities.push('log_driven_debugging');
    88|  if (architecture) capabilities.push('feature_architecture');
    89|  if (novel) capabilities.push('novel_problem_adaptation');
    90|  if (delivery || capabilities.length === 0) capabilities.push('continuous_delivery');
    91|  return unique(capabilities);
    92|}
    93|
    94|function findSymptom(goal: string): string | null {
    95|  const match = goal.match(/(?:because|when|where|that|is|are)\s+([^.!?]{4,180}(?:crash|error|fail|broken|slow|stuck|timeout|blank|loading)[^.!?]*)/i);
    96|  if (match?.[1]) return match[1].trim();
    97|  const explicit = goal.match(/\b(?:crash|error|failure|timeout|blank screen|stuck loading|not loading)\b[^.!?]*/i);
    98|  return explicit?.[0]?.trim() ?? null;
    99|}
