   101|/**
   102| * Creates a deterministic task contract. The runtime stores this contract with
   103| * the execution proof, so a result can be audited without trusting narrative.
   104| */
   105|export function buildSeniorDeveloperTaskContract(goal: string): IVXSeniorDeveloperTaskContract {
   106|  const trimmedGoal = goal.trim();
   107|  if (!trimmedGoal) throw new Error('A goal is required to build an engineering task contract.');
   108|  const capabilities = classifySeniorDeveloperCapabilities(trimmedGoal);
   109|  const hasDebug = capabilities.includes('log_driven_debugging');
   110|  const hasArchitecture = capabilities.includes('feature_architecture');
   111|  const hasNovel = capabilities.includes('novel_problem_adaptation');
   112|  const hasVagueBuild = capabilities.includes('vague_goal_code_generation');
   113|  const symptom = findSymptom(trimmedGoal);
   114|
   115|  const assumptions = [
   116|    'The current repository is the source of truth for implementation decisions.',
   117|    'No secret-bearing file may be read into an execution report or modified by an automated patch.',
   118|  ];
   119|  if (hasVagueBuild) assumptions.push('Unspecified product details will be expressed as explicit assumptions and implemented as the smallest testable vertical slice.');
   120|  if (hasDebug) assumptions.push('A symptom is not treated as a root cause until repository evidence or runtime logs falsify competing explanations.');
   121|  if (hasNovel) assumptions.push('Novel requests are decomposed into known primitives before implementation; unsupported dependencies are surfaced rather than invented.');
   122|
   123|  const discoveryQuestions = [
   124|    'Which existing files, routes, and tests own the affected behavior?',
   125|    'What is the smallest observable acceptance condition for this task?',
   126|  ];
   127|  if (hasDebug) discoveryQuestions.push('Which log line, stack frame, request trace, or failing assertion distinguishes the leading hypothesis from alternatives?');
   128|  if (hasArchitecture) discoveryQuestions.push('Which data boundary, API contract, client state, and rollback path are required for the feature to be complete?');
   129|
   130|  const executionStages = [
   131|    'inspect_repository',
   132|    ...(hasDebug ? ['collect_and_normalize_signals', 'form_and_falsify_hypotheses'] : []),
   133|    ...(hasArchitecture ? ['define_interfaces_and_failure_modes'] : []),
   134|    ...(hasVagueBuild ? ['implement_smallest_testable_vertical_slice'] : ['prepare_safe_patch']),
   135|    'run_targeted_tests',
   136|    'run_typecheck_or_build',
   137|    'review_evidence',
   138|    'commit_and_deploy_when_explicitly_approved',
   139|    'verify_live_health_and_requested_commit',
   140|  ];
   141|
   142|  const likelyCauses = hasDebug
   143|    ? ['Regression in the owning code path.', 'Invalid or missing runtime configuration.', 'Unexpected external dependency response.', 'Incorrect state or data-shape assumption.']
   144|    : [];
   145|  const falsificationSignals = hasDebug
   146|    ? ['A focused test reproduces the failure.', 'A relevant log or stack trace points to the owning path.', 'A minimal change removes the failure without masking the signal.']
   147|    : [];
   148|
   149|  const evidenceRequirements: IVXEngineeringEvidenceRequirement[] = [
   150|    { kind: 'repository_inspection', required: true, reason: 'Implementation choices must be grounded in current source.' },
   151|    { kind: 'implementation', required: true, reason: 'A completion claim requires an actual changed-file record.' },
   152|    { kind: 'test_result', required: true, reason: 'The requested behavior needs a reproducible validation result.' },
   153|    { kind: 'typecheck_result', required: true, reason: 'The changed code must pass the applicable static or build check.' },
   154|    { kind: 'commit', required: true, reason: 'A deployable result must identify the immutable source revision.' },
   155|    { kind: 'deployment', required: true, reason: 'Production claims require a deployment result.' },
   156|    { kind: 'production_verification', required: true, reason: 'A deployment alone does not prove the requested behavior is live.' },
   157|  ];
   158|  if (hasDebug) {
   159|    evidenceRequirements.splice(1, 0,
   160|      { kind: 'log_signal', required: true, reason: 'Debugging requires a real observed signal, not a guessed cause.' },
   161|      { kind: 'hypothesis', required: true, reason: 'The chosen fix must state what evidence would have disproved it.' },
   162|    );
   163|  }
   164|
   165|  return {
   166|    marker: IVX_SENIOR_DEVELOPER_CAPABILITY_MARKER,
   167|    goal: trimmedGoal,
   168|    taskId: stableTaskId(trimmedGoal),
   169|    capabilities,
   170|    summary: `Engineering contract for ${capabilities.join(', ')}.`,
   171|    assumptions,
   172|    discoveryQuestions,
   173|    executionStages,
   174|    hypothesis: { symptom, likelyCauses, falsificationSignals },
   175|    architecture: {
   176|      boundaries: hasArchitecture ? ['client presentation', 'owner-authorized API', 'durable data', 'deployment verification'] : ['affected module boundary'],
   177|      interfaces: hasArchitecture ? ['request contract', 'response contract', 'failure contract', 'evidence contract'] : ['existing affected interfaces'],
   178|      risks: ['unsafe broad patch', 'unrelated pre-existing test failures', 'deployment verification timeout'],
   179|    },
   180|    adaptation: {
   181|      isNovel: hasNovel,
   182|      approach: hasNovel ? 'Map the unfamiliar request to repository primitives, validate assumptions with a focused spike, then promote only verified behavior into the patch.' : 'Use existing repository conventions and narrow the task to an observable behavior.',
   183|      fallback: 'Stop before mutation when the repository or evidence contradicts the contract; report the missing evidence and retain the audit trail.',
   184|    },
   185|    evidenceRequirements,
   186|    requiresOwnerApprovalForMutation: true,
   187|    requiresOwnerApprovalForDeployment: true,
   188|  };
   189|}

